def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell value can be collected at most once, even if both paths pass through it.
    """
    # Build grid
    grid = [[0] * N for _ in range(N)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x - 1][y - 1] = val

    # Edge case: single cell
    if N == 1:
        return grid[0][0]

    # Initialize DP arrays
    NEG_INF = -10**18
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[0][0]

    # Iterate over steps k = i1 + j1 = i2 + j2
    for k in range(2, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG_INF
                # four possible previous moves
                for di1 in (0, 1):
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        prev = dp_prev[pi1][pi2]
                        if prev > best:
                            best = prev
                if best == NEG_INF:
                    continue
                add = 0
                if i1 == i2 and j1 == j2:
                    add = grid[i1 - 1][j1 - 1]
                else:
                    add = grid[i1 - 1][j1 - 1] + grid[i2 - 1][j2 - 1]
                dp_cur[i1][i2] = best + add
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != NEG_INF else 0

def cantor_numbering(N: int) -> str:
    s = 2
    while (s-1)*s//2 < N:
        s += 1
    prev = (s-2)*(s-1)//2
    offset = N - prev
    if s % 2 == 0:
        numerator = s - offset
        denominator = offset
    else:
        numerator = offset
        denominator = s - offset
    return f"{numerator}/{denominator

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product obtainable by inserting K multiplication signs into the
    numeric string `num_str` of length N. The string is split into K+1 contiguous
    substrings, each interpreted as an integer (leading zeros are allowed).
    """
    if N == 0:
        return 0
    if K == 0:
        return int(num_str)
    if K > N - 1:
        # Not enough positions to place K multiplications
        return 0

    # dp[i][k] = maximum product for prefix num_str[:i] using k multiplications
    # i ranges from 1 to N inclusive
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: no multiplications, product is the integer value of the prefix
    for i in range(1, N + 1):
        dp[i][0] = int(num_str[:i])

    # Fill DP table
    for i in range(1, N + 1):
        for k in range(1, min(K, i - 1) + 1):
            max_prod = 0
            # Split at position j: last number is num_str[j:i]
            for j in range(k, i):
                left_prod = dp[j][k - 1]
                right_num = int(num_str[j:i])
                prod = left_prod * right_num
                if prod > max_prod:
                    max_prod = prod
            dp[i][k] = max_prod

    return dp[N][K]

def calculate_scholarship(grades: List[int], leader: str, west: str, papers: int) -> int:
    avg, eval_score = grades
    scholarship = 0
    if avg > 80 and papers > 0:
        scholarship += 8000
    if avg > 85 and eval_score > 80:
        scholarship += 4000
    if avg > 90:
        scholarship += 2000
    if avg > 85 and west == 'Y':
        scholarship += 1000
    if eval_score > 80 and leader == 'Y':
        scholarship += 850
    return scholarship

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    first_term = True
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine variable part
        if degree == 0:
            var = ''
        elif degree == 1:
            var = 'x'
        else:
            var = f'x^{degree}'

        # Determine coefficient part
        if abs_coeff == 1 and degree > 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)

        term = f"{sign}{coeff_part}{var}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.
    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    start = str(n)
    visited = {start}
    queue = [start]

    # Preprocess rules into a dictionary for quick lookup
    rule_map = {}
    for x, y in rules:
        rule_map.setdefault(x, []).append(y)

    while queue:
        current = queue.pop(0)
        for i, ch in enumerate(current):
            if not ch.isdigit():
                continue
            digit = int(ch)
            if digit in rule_map:
                for new_digit in rule_map[digit]:
                    new_num = current[:i] + str(new_digit) + current[i+1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine truth value of a statement given the scenario and speaker
    def evaluate_statement(statement: str, speaker: str) -> bool:
        stmt = statement.strip().rstrip('.').lower()
        # Ignore statements about days of the week
        if any(day.lower() in stmt for day in days_of_week):
            return None  # indicates to skip

        # Handle "I am guilty." / "I am not guilty."
        if stmt.startswith("i am guilty"):
            return scenario == speaker
        if stmt.startswith("i am not guilty"):
            return scenario != speaker

        # Handle "X is guilty." / "X is not guilty."
        if " is guilty" in stmt:
            subject = stmt.split(" is guilty")[0].strip()
            return scenario == subject.upper()
        if " is not guilty" in stmt:
            subject = stmt.split(" is not guilty")[0].strip()
            return scenario != subject.upper()

        # If statement format not recognized, treat as neutral (skip)
        return None

    for speaker, stmts in statements.items():
        for stmt in stmts:
            truth = evaluate_statement(stmt, speaker)
            if truth is None:
                continue  # skip unrecognized or day-related statements
            is_liar = speaker in liar_count
            if is_liar and truth:
                return False  # liar said a true statement
            if not is_liar and not truth:
                return False  # truth-teller said a false statement
    return True

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    # Sort intervals by start point
    intervals = sorted(areas, key=lambda x: x[0])
    merged = []
    for start, end in intervals:
        # Clamp to road bounds
        start = max(0, start)
        end = min(l, end)
        if start >= end:
            continue
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    total_cleared = sum(end - start for start, end in merged)
    remaining = l - total_cleared
    return max(0, remaining)

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    if m > sum(a):
        return 0
    dp_prev = [0] * (m + 1)
    dp_prev[0] = 1
    for i in range(n):
        limit = a[i]
        dp_cur = [0] * (m + 1)
        prefix = [0] * (m + 1)
        prefix[0] = dp_prev[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + dp_prev[j]) % MOD
        for j in range(m + 1):
            low = j - limit
            if low <= 0:
                dp_cur[j] = prefix[j]
            else:
                dp_cur[j] = (prefix[j] - prefix[low - 1]) % MOD
        dp_prev = dp_cur
    return dp_prev[m] % MOD

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
    heights (List[int]): A list of student heights.

    Returns:
    int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 2:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Longest bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
